------------------
---- MONITORS ----
------------------

-- i3 equivalent: xrandr --output DP-4 --mode 3440x1440 --rate 165
-- Matched by description so it works on any port (check `hyprctl monitors` for the desc).
hl.monitor({
    output   = "desc:Samsung Electric Company LC34G55T HNTW302306",
    mode     = "3440x1440@165",
    position = "0x0",
    scale    = 1,
})


---------------------
---- MY PROGRAMS ----
---------------------

local terminal = "alacritty"

-- i3-style launcher: rofi drun/run (Wayland build)
local menu = "rofi -modi drun,run -show drun"


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- Point everything at the systemd ssh-agent (ssh-agent.socket) so KeePassXC and
-- shells share one agent; ZSH/linux.zsh skips keychain when this socket exists.
hl.env("SSH_AUTH_SOCK", os.getenv("XDG_RUNTIME_DIR") .. "/ssh-agent.socket")


