-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    -- Share SSH_AUTH_SOCK with D-Bus/systemd-activated apps too
    hl.exec_cmd("dbus-update-activation-environment --systemd SSH_AUTH_SOCK")

    -- XDG autostart (if you relied on it in i3)
    hl.exec_cmd("dex --autostart --environment hyprland")
    hl.exec_cmd("waybar")

    hl.exec_cmd("hyprpaper")

    -- Notifications (Wayland-native). If you want dunst, swap to `dunst`.
    hl.exec_cmd("mako")

    -- Network tray
    hl.exec_cmd("nm-applet")

    -- Screen locking / idle (replaces xss-lock + xsecurelock)
    hl.exec_cmd("hypridle")
    -- hl.exec_cmd("hyprlock")  -- disabled: greetd already authenticates at login

    -- Polkit agent for GUI auth prompts
    hl.exec_cmd("/usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1")
end)


---------------------
---- KEYBINDINGS ----
---------------------

local mod = "SUPER" -- main modifier

-- --- Core (i3 muscle memory) ---
hl.bind(mod .. " + Return",        hl.dsp.exec_cmd(terminal))
hl.bind(mod .. " + SHIFT + Q",     hl.dsp.window.close())

-- i3: $mod+d -> rofi
hl.bind(mod .. " + D", hl.dsp.exec_cmd(menu))

-- i3 focus / move window: hjkl-style (j k l ;) and arrows
local directions = {
    { keys = { "J", "left" },         dir = "left" },
    { keys = { "K", "down" },         dir = "down" },
    { keys = { "L", "up" },           dir = "up" },
    { keys = { "semicolon", "right" }, dir = "right" },
}
for _, d in ipairs(directions) do
    for _, key in ipairs(d.keys) do
        hl.bind(mod .. " + " .. key,           hl.dsp.focus({ direction = d.dir }))
        hl.bind(mod .. " + SHIFT + " .. key,   hl.dsp.window.move({ direction = d.dir }))
    end
end

-- i3 fullscreen (old `fullscreen, 1` = maximize)
hl.bind(mod .. " + F", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))

-- i3 floating toggle
hl.bind(mod .. " + SHIFT + space", hl.dsp.window.float({ action = "toggle" }))

-- i3 focus mode_toggle (closest: cycle next)
hl.bind(mod .. " + space", hl.dsp.window.cycle_next())

-- i3 focus parent (no direct equivalent; use "last/urgent" as a practical stand-in)
hl.bind(mod .. " + A", hl.dsp.focus({ urgent_or_last = true }))

-- Workspaces 1..10, and move window to workspace (silently)
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i, follow = false }))
end

-- i3 reload config
hl.bind(mod .. " + SHIFT + C", hl.dsp.exec_cmd("hyprctl reload"))

-- i3 lock key (your i3 used $mod+Shift+w)
hl.bind(mod .. " + SHIFT + W", hl.dsp.exec_cmd("hyprlock"))

-- --- Resize "mode" (i3-style) ---
hl.bind(mod .. " + R", hl.dsp.submap("resize"))

hl.define_submap("resize", function()
    -- j/k/l/; behavior matching your i3 resize mode semantics
    local resizes = {
        { keys = { "J", "left" },          x = -10, y = 0 },
        { keys = { "semicolon", "right" }, x = 10,  y = 0 },
        { keys = { "K", "down" },          x = 0,   y = 10 },
        { keys = { "L", "up" },            x = 0,   y = -10 },
    }
    for _, r in ipairs(resizes) do
        for _, key in ipairs(r.keys) do
            hl.bind(key, hl.dsp.window.resize({ x = r.x, y = r.y, relative = true }), { repeating = true })
        end
    end

    hl.bind("Return",       hl.dsp.submap("reset"))
    hl.bind("Escape",       hl.dsp.submap("reset"))
    hl.bind(mod .. " + R",  hl.dsp.submap("reset"))
end)

-- --- Media keys (your i3 pactl + xbindkeys playerctl) ---
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ +10%"))
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("pactl set-sink-volume @DEFAULT_SINK@ -10%"))
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("pactl set-sink-mute @DEFAULT_SINK@ toggle"))
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("pactl set-source-mute @DEFAULT_SOURCE@ toggle"))

hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"))
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl pause"))
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"))
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"))

-- --- DDC controls (your xbindkeys: mod4 + insert/home) ---
hl.bind(mod .. " + Insert", hl.dsp.exec_cmd("ddcutil --display 1 setvcp 60 6"))
hl.bind(mod .. " + Home",   hl.dsp.exec_cmd("ddcutil --display 1 setvcp 60 9"))

-- --- Screenshots (Wayland-native replacements for maim/xdotool/xclip) ---
local shotFile = [["$HOME/Pictures/$(date +%F_%H-%M-%S).png"]]
-- Geometry of the active window, as "X,Y WxH" for grim -g
local activeGeom = [[hyprctl -j activewindow | jq -r '"\(.at[0]),\(.at[1]) \(.size[0])x\(.size[1])"']]

-- Fullscreen to file
hl.bind("Print",                hl.dsp.exec_cmd("grim " .. shotFile))
-- Region to file
hl.bind("SHIFT + Print",        hl.dsp.exec_cmd([[grim -g "$(slurp)" ]] .. shotFile))
-- Clipboard fullscreen
hl.bind("CTRL + Print",         hl.dsp.exec_cmd("grim - | wl-copy -t image/png"))
-- Clipboard region
hl.bind("CTRL + SHIFT + Print", hl.dsp.exec_cmd([[grim -g "$(slurp)" - | wl-copy -t image/png]]))
-- Active window to file (replacement for: maim --window $(xdotool getactivewindow))
hl.bind(mod .. " + Print",          hl.dsp.exec_cmd(activeGeom .. [[ | xargs -I{} grim -g "{}" ]] .. shotFile))
-- Clipboard active window
hl.bind("CTRL + " .. mod .. " + Print", hl.dsp.exec_cmd(activeGeom .. [[ | xargs -I{} grim -g "{}" - | wl-copy -t image/png]]))

-- --- Workspace scroll + mouse move/resize (kept from autogenerated) ---
hl.bind(mod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

hl.bind(mod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })


