---- WINDOWS AND WORKSPACES ----
--------------------------------

-- Keep this
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Your i3 for_window rules -> Hyprland window rules
hl.window_rule({
    name  = "float-steam",
    match = { class = "^(Steam)$" },
    float = true,
})

hl.window_rule({
    name  = "float-steamwebhelper",
    match = { class = "^(steamwebhelper)$" },
    float = true,
})

hl.window_rule({
    name  = "fzfpopup",
    match = { class = "^(fzfpopup)$" },
    float = true,
    move  = { 1000, 50 },
    size  = { 400, 300 },
})
